import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.S-Qvb3wi.js";const p=JSON.parse('{"title":"Discord Bot Commands","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/discord/bot-commands.md","filePath":"user-guide/discord/bot-commands.md"}'),s={name:"user-guide/discord/bot-commands.md"};function n(i,e,m,l,d,c){return t(),r("div",null,e[0]||(e[0]=[o('<h1 id="discord-bot-commands" tabindex="-1">Discord Bot Commands <a class="header-anchor" href="#discord-bot-commands" aria-label="Permalink to &quot;Discord Bot Commands&quot;">​</a></h1><p>The Citizen iD Discord bot offers a variety of slash commands to help users manage their accounts and assisting server administrators in maintaining their community.</p><h2 id="account-management" tabindex="-1">Account Management <a class="header-anchor" href="#account-management" aria-label="Permalink to &quot;Account Management&quot;">​</a></h2><p>These commands allow users to manage their Citizen iD account directly from Discord.</p><ul><li><p><strong>/account create</strong><br>Prompt a user to create a Citizen iD account. This is useful for onboarding new members.</p></li><li><p><strong>/account set-display-name</strong><br>Update your display name preferences. This allows you to change your global or server specific display name.</p></li><li><p><strong>/account unset-display-name</strong><br>Remove your custom display name preference and revert to the default behavior.</p></li></ul><h2 id="rsi-profile" tabindex="-1">RSI Profile <a class="header-anchor" href="#rsi-profile" aria-label="Permalink to &quot;RSI Profile&quot;">​</a></h2><p>Commands for interacting with RSI profile data.</p><ul><li><p><strong>/rsi profile</strong><br>Retrieve and display information about an RSI profile, such as verification status and organization memberships.</p></li><li><p><strong>/rsi refresh</strong><br><em>(Admin Only)</em> Force a refresh of RSI profile data for a specific user. This is useful if a user&#39;s data appears out of sync.</p></li></ul><h2 id="role-management" tabindex="-1">Role Management <a class="header-anchor" href="#role-management" aria-label="Permalink to &quot;Role Management&quot;">​</a></h2><ul><li><strong>/roles update</strong><br>Request an immediate update of all user roles on the current server. <br><em>Note: This command requires the &quot;Manage Roles&quot; permission to be used.</em></li></ul><h2 id="system-administration" tabindex="-1">System Administration <a class="header-anchor" href="#system-administration" aria-label="Permalink to &quot;System Administration&quot;">​</a></h2><p>These commands are intended for bot administrators and debugging purposes.</p><ul><li><p><strong>/system reverify</strong><br><em>(Admin Only)</em> Force the system to re-verify an account&#39;s status.</p></li><li><p><strong>/system resync-state</strong><br><em>(Admin Only)</em> Force a complete re-sync of an account&#39;s state across all services.</p></li><li><p><strong>/system health</strong><br>Display a health report for the bot and its connected services.</p></li></ul><hr><p><em>Last updated: February 2026</em></p>',15)]))}const h=a(s,[["render",n]]);export{p as __pageData,h as default};
